t.script:
(function() {
    var orderId = ;

    function complete() {
        if (window.opener) {
            window.opener.postMessage('payment_done', '*');
            window.close();
        } else {
            window.location.replace('/odoo/sales/' + orderId);
        }
    }

    (function poll() {
        fetch('/payment/status/poll', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', id: 1, params: {} }),
        })
        .then(function(r) { return r.json(); })
        .then(function(data) {
            var state = data.result && data.result.state;
            if (!state || state === 'draft' || state === 'pending') {
                setTimeout(poll, 500);
            } else {
                complete();
            }
        })
        .catch(function() { setTimeout(poll, 1000); });
    })();
})();
